<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string|null $reporter_id
 * @property string $target_type
 * @property string $target_id
 * @property string $reason
 * @property string|null $detail
 * @property string $severity
 * @property string $source
 * @property string $status
 * @property string|null $assignee_id
 * @property string|null $resolution
 * @property string|null $resolution_note
 * @property string|null $resolved_by
 * @property Carbon|null $resolved_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Report extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'rep';

    protected $fillable = [
        'reporter_id', 'target_type', 'target_id', 'reason', 'detail', 'severity', 'source', 'status', 'assignee_id',
        'resolution', 'resolution_note', 'resolved_by', 'resolved_at',
    ];

    protected function casts(): array
    {
        return [
            'resolved_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function reporter(): BelongsTo
    {
        return $this->belongsTo(User::class, 'reporter_id');
    }

    /** @return BelongsTo<User, $this> */
    public function assignee(): BelongsTo
    {
        return $this->belongsTo(User::class, 'assignee_id');
    }
}
